def admit(active, waiting, budget, slots):
    # Reject if any waiting reservation exceeds the total budget,
    # even if the FIFO pass would stop before reaching it.
    for value in waiting:
        if value > budget:
            raise ValueError(
                f"reservation {value} exceeds total budget {budget}"
            )

    admitted = []
    used_budget = sum(active)
    used_slots = len(active)

    for value in waiting:
        # Stop at the first reservation that does not fit in budget or slots.
        if (
            used_budget + value > budget
            or used_slots + 1 > slots
        ):
            break
        admitted.append(value)
        used_budget += value
        used_slots += 1

    remaining = waiting[len(admitted):]
    return admitted, remaining

def endpoint(base_url, path):
    base = base_url.rstrip('/')
    if base.rsplit('/', 1)[-1] != 'v1':
        base = base + '/v1'
    return base + '/' + path.lstrip('/')

